import {workboard} from './workboard-ui.js';
import {dutyPanel,incidentPanel} from './duty-ui.js';
import {createClock} from './duty-clock.js';
import {plain,sceneActions,briefing,terminal,handover,results,supportPanel} from './flow-ui.js';
import {createState,act,can,objective,outcome,timeText,restoreState,DIFFICULTIES,CASE_ID,ROUTINE_ID,workflow,dateText,mainWorkDone,SHIFT_END} from './engine.js';

const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const SAVE='barn-door-first-shift-v1', SETTINGS='barn-door-settings-v1';
let state=createState(), started=false, activePanel=null,selectedEvent=null,returnFocus=null,returnFocusKey=null,toastTimer;
let settings={sound:false,volume:0.25,captions:true,large:false,motion:false};
try{settings={...settings,...JSON.parse(localStorage.getItem(SETTINGS)||'{}')};}catch{}
const esc=v=>plain(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={book:'M4 4h7v15H4z M11 4h9v15h-9 M7 8h1 M14 8h3 M14 12h3',people:'M8 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M2 20v-3a5 5 0 0 1 10 0v3 M16 5a3 3 0 0 1 0 6 M16 14a5 5 0 0 1 6 5v1',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',sound:'M4 9h4l5-4v14l-5-4H4z M17 8q5 4 0 8 M19 4q9 8 0 16',heart:'M12 20 3 11C-1 4 7 1 12 7c5-6 13-3 9 4z',bed:'M3 4v16 M3 15h18v5 M3 9h6v6 M9 10h10q2 0 2 2v3',pulse:'M2 12h5l3-8 4 16 3-8h5',meal:'M5 3v7q0 2 2 2V3 M3 3v7q0 2 2 2v9 M17 3q-4 5-2 9h3 M18 3v18',gate:'M4 21V3h16v18 M8 3v18 M16 3v18 M2 21h20 M11 11h2',tool:'m14 5 5-3-1 6-4 3-9 10-3-3 10-9z',close:'m6 6 12 12 M18 6 6 18',check:'m4 12 5 5L20 6',arrow:'M4 12h16 M14 6l6 6-6 6',file:'M6 3h8l4 4v14H6z M14 3v5h4 M9 12h6 M9 16h6',radio:'M5 7h14v14H5z M8 7 17 2 M8 11h8 M8 15h8 M8 18h3'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.file).split(' M').map((d,i)=>`<path d="${i?'M':''}${d}"/>`).join('')}</svg>`;}
function icons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5200);}
function saved(){try{return restoreState(localStorage.getItem(SAVE));}catch{return null;}}
function save(){try{localStorage.setItem(SAVE,JSON.stringify(state));}catch{toast('瀏覽器無法儲存；可從事件簿匯出本次紀錄。');}}
function setSettings(){document.documentElement.style.setProperty('--scale',settings.large?'1.12':'1');document.body.classList.toggle('large-text',settings.large);document.body.classList.toggle('reduced-motion',settings.motion);$('#sound-caption').hidden=!settings.captions;$('#sound-label').textContent=settings.sound?'音效開啟':'音效關閉';$('#sound-toggle').setAttribute('aria-label',settings.sound?'關閉音效':'開啟音效');$('#sound-toggle').setAttribute('aria-pressed',String(settings.sound));try{localStorage.setItem(SETTINGS,JSON.stringify(settings));}catch{}audio.setVolume();}
const audio={ctx:null,gain:null,init(){if(this.ctx)return;try{this.ctx=new (window.AudioContext||window.webkitAudioContext)();this.gain=this.ctx.createGain();this.gain.gain.value=0;this.gain.connect(this.ctx.destination);const oscillator=this.ctx.createOscillator();oscillator.type='sine';oscillator.frequency.value=74;const low=this.ctx.createGain();low.gain.value=.09;oscillator.connect(low);low.connect(this.gain);oscillator.start();const length=this.ctx.sampleRate*3,buffer=this.ctx.createBuffer(1,length,this.ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<length;i++)data[i]=Math.random()*2-1;const source=this.ctx.createBufferSource();source.buffer=buffer;source.loop=true;const filter=this.ctx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=360;const noise=this.ctx.createGain();noise.gain.value=.09;source.connect(filter);filter.connect(noise);noise.connect(this.gain);source.start();}catch{toast('這個瀏覽器無法啟用合成音效，文字提示仍可使用。');}},setVolume(){if(this.gain)this.gain.gain.setTargetAtTime(settings.sound?settings.volume:0,this.ctx.currentTime,.12);},async resume(){this.init();if(this.ctx?.state==='suspended')await this.ctx.resume();this.setVolume();},click(){if(!settings.sound||!this.ctx)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.frequency.setValueAtTime(650,this.ctx.currentTime);o.frequency.exponentialRampToValueAtTime(340,this.ctx.currentTime+.07);g.gain.setValueAtTime(.025*settings.volume,this.ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,this.ctx.currentTime+.08);o.connect(g);g.connect(this.ctx.destination);o.start();o.stop(this.ctx.currentTime+.08);}};
const LOCATIONS={dorm:{code:'RESIDENTIAL / B-02',title:'生活區寢室',description:'乾燥的床位，正常的通風。今天還沒有什麼不一樣。',caption:'通風機平穩運轉。隔床傳來輕微夢話。',machine:'PERSONAL LOCKER',interaction:'床邊置物櫃'},canteen:{code:'COMMUNAL / C-01',title:'公共餐廳',description:'暖燈、熱食，還有剛下夜班的人。',caption:'餐盤輕碰。抽風機運轉，後勤在核對留餐。',machine:'MEAL SERVICE',interaction:'配給窗口'},gate:{code:'ACCESS CONTROL / B-01',title:'守門控制室',description:'窗外是接收區，身後是大家生活的地方。',caption:'對講機待命。門機低鳴，位置感測器正常。',machine:'GATE INTERLOCK',interaction:'門禁工作台'},engineering:{code:'ENGINEERING / E-01',title:'工程維護區',description:'設備完整運作。維護，是讓平常日子繼續的工作。',caption:'泵浦規律轉動。工程師在檢查維修表。',machine:'SERVICE ACCESS',interaction:'工程巡檢窗口'}};
const b=(label,action,cls='secondary',data='')=>`<button class="${cls}" data-action="${action}" ${data}>${label}</button>`;
const ui=(label,panel,cls='secondary')=>`<button class="${cls}" data-ui="${panel}">${label}</button>`;
function actionItem(action,label,detail='',danger=false){const reason=can(state,action);return `<div class="action-item"><button class="${danger?'danger-button':'secondary'}" data-action="${action}" ${reason?'disabled':''}>${esc(label)}</button><small>${esc(reason||detail)}</small></div>`;}
function render(){
 const l=LOCATIONS[state.location];$('#date').textContent=dateText(state);$('#day-counter').textContent=`第 ${state.day||1} 天 / 共 3 天`;$('#scene').className=`scene scene--${state.location}`;$('#clock').textContent=timeText(state.time);$('#weather').textContent=state.time>=780?'短暫雷雨 · 25°C':'多雲 · 26°C';$('#location-code').textContent=l.code;$('#location-title').textContent=l.title;$('#location-description').textContent=l.description;$('#sound-caption span:last-child').textContent=l.caption;$('#objective').textContent=objective(state);$('#duty-label').textContent=state.ended?'值勤完成':mainWorkDone(state)&&state.time<SHIFT_END?'待命中 · 16:00 交班':state.signed?'守門值勤 · 事件處理':'晨間準備';updateClockMode();$('#interaction-title').textContent=l.interaction;$('#machine-label').textContent=l.machine;$('#scene-message').textContent=plain(state.last);
 for(const key of ['stamina','fatigue','pressure']){$(`#${key}`).textContent=state[key];$(`#${key}-meter`).value=state[key];$(`#${key}-meter`).setAttribute('aria-label',`${{stamina:'體力',fatigue:'疲勞',pressure:'壓力'}[key]} ${state[key]}`);}
 $$('.location-nav button').forEach(el=>{el.setAttribute('aria-current',state.location===el.dataset.move?'location':'false');el.disabled=state.ended;});$('#journal-dot').hidden=!state.events.length;updateWorkboardCount();
 const stage=workflow(state).stage;$('#progress').innerHTML=['準備','接班','工作','交班'].map((label,i)=>`<span class="${i<stage?'complete':i===stage?'current':''}">${i+1} ${label}</span>`).join('');
 const actions=sceneActions(state,{b,ui});
 $('#actions').innerHTML=actions;$$('#actions [data-action]').forEach(el=>{const reason=can(state,el.dataset.action);if(reason){el.disabled=true;el.title=reason;}});
 const spots={dorm:[['置物櫃','inventory',32,42],['上一班的提醒','briefing',65,34]],canteen:[['配給窗口','logistics',36,40],['上一班的提醒','briefing',65,31]],gate:[['門禁終端','terminal',28,49],['對講機','visitor',53,43]],engineering:[['工程師','engineer',61,42],['設備工單','routine',28,34]]}[state.location];$('#hotspots').innerHTML=state.ended?'':spots.map(([label,panel,x,y],i)=>`<button class="hotspot" data-ui="${panel}" style="left:${x}%;top:${y}%"><span class="pin">${i+1}</span>${label}</button>`).join('');
 icons($('#game'));plainDom($('#game'));setSettings();
}
function plainDom(root){const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walk.nextNode()){node.textContent=plain(node.textContent);}}
function run(action,payload={}){const result=act(state,action,payload);if(result.error){toast(result.error);return false;}state=result.state;save();render();audio.click();if(state.ended){openPanel('result');return true;}if(activePanel==='terminal'||activePanel==='roster'||activePanel==='journal'||activePanel==='routine'||activePanel==='briefing'||activePanel==='handover'||activePanel==='visitor'||activePanel==='engineer'||activePanel==='logistics'||activePanel==='standby'||activePanel==='incident'||activePanel==='workboard')renderPanel();if(state.activeIncident&&activePanel!=='incident')openPanel('incident');toast(state.last);return true;}
function download(name,content,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openPanel(panel){if(!$('#tool-dialog').open){returnFocus=document.activeElement;returnFocusKey=returnFocus?.dataset?{...returnFocus.dataset}:null;$('#tool-dialog').showModal();}activePanel=panel;if(panel==='journal')selectedEvent=null;renderPanel();$('#dialog-content').scrollTop=0;}
function closePanel(){$('#tool-dialog').close();activePanel=null;let target=returnFocus?.isConnected?returnFocus:null;if(!target&&returnFocusKey){target=$$('button').find(el=>Object.entries(returnFocusKey).some(([key,value])=>['ui','action','move'].includes(key)&&el.dataset[key]===value)&&!el.disabled&&el.getClientRects().length);}if(!target||!target.getClientRects().length)target=$$('#game button,#landing button').find(el=>!el.disabled&&el.getClientRects().length);target?.focus();}
function header(title,code){$('#dialog-title').textContent=title;$('#dialog-code').textContent=code;}
function renderPanel(){const c=$('#dialog-content');const previous=document.activeElement;const hadFocus=c.contains(previous);const focusData=hadFocus?{...previous.dataset}:null;const focusIndex=hadFocus?[...c.querySelectorAll('button:not(:disabled),input,textarea,select,summary')].indexOf(previous):-1;
 switch(activePanel){
 case 'workboard':workboard(state,{header,c,b,ui,esc});break;
 case 'standby':dutyPanel(state,{header,c,b,ui,esc});break;
 case 'incident':incidentPanel(state,{header,c,b,ui,esc});break;
 case 'briefing':briefing(state,{header,c,b,ui,esc});break;
 case 'help':header('怎麼玩這三天','PLAY GUIDE');c.innerHTML=`<p class="lead">你是今天的守門人。庇護所已經運作一段時間，先看看前幾班的工作，再跟著右上角的提醒。</p><ol class="briefing-list"><li><strong>起床，吃早餐。</strong><span>拿好工作服和識別證，再去餐廳。</span></li><li><strong>聽上一班交代，接手工作。</strong><span>先看交接待辦，分清楚誰在做什麼。讀過今天的提醒，再到守門室接班。</span></li><li><strong>處理今天的事。</strong><span>先問清楚，再決定。忙不過來可以請同事幫忙，不必自己全做。</span></li><li><strong>交代清楚，再下班。</strong><span>把做過的事和沒做完的事交給同事。他答應接手後，才能休息到隔天。</span></li></ol><p class="section-title">三天會遇到什麼？</p><p class="lead">第一天收貨，多了一箱東西。第二天追蹤昨天的事，修理指紋機。第三天可能下大雨，送貨地點又有變動。</p><div class="notice">點畫面上的按鈕。J 開事件簿、R 看人員名單、Esc 關閉視窗。看說明會暫停時鐘。主要工作完成後，每秒推進遊戲一分鐘，繼續待命到下午四點。有狀況時先停下來回應。進度會自動存在這個瀏覽器。</div><details><summary>這版試玩的範圍</summary><p class="lead">場景是固定圖片，可以點選切換，人物還不會走動。聲音先用簡單底噪，沒有配音。這次只有三天，還沒有全年遊戲。</p></details>`;break;
 case 'inventory':header('隨身裝備','PERSONAL KIT');c.innerHTML=`<p class="lead">${state.gear?'識別證、工作外套與通訊器已備妥。生活區不需要全套防護衣，進檢疫區時再依程序穿戴。':'你的工作裝備仍在床邊置物櫃裡。'}</p><div class="notice">手寫標籤：<span class="tape">濾芯別拿錯</span></div><div class="dialog-actions">${!state.gear?b('取工作裝備 · 4 分鐘','gear','primary'):ui('查看工作名冊','roster','primary')}</div>`;break;
 case 'roster':renderRoster(c);break;
 case 'terminal':renderTerminal(c);break;
 case 'journal':renderJournal(c);break;
 case 'routine':supportPanel('routine',state,{header,c,b,ui,esc,timeline});break;
 case 'visitor':supportPanel('visitor',state,{header,c,b,ui,esc,timeline});break;
 case 'engineer':supportPanel('engineer',state,{header,c,b,ui,esc,timeline});break;
 case 'logistics':supportPanel('logistics',state,{header,c,b,ui,esc,timeline});break;
 case 'handover':renderHandover(c);if(state.time>=SHIFT_END){const inherited=(state.inheritedJobs||[]).filter(j=>j.status!=='已完成');if(inherited.length)c.innerHTML+='<h3 class="section-title">接過來的工作，還有這些後續</h3><ul class="help-list">'+inherited.map(j=>'<li>'+esc(j.title)+'：'+esc(j.owner)+'負責。'+esc(j.next)+'</li>').join('')+'</ul>';const pending=state.events.filter(e=>e.category==='待命事件'&&e.status!=='已結案');c.innerHTML+=`<h3 class="section-title">待命期間的事</h3><p class="lead">今天回應了 ${(state.dutyHandled||[]).length} 件狀況。</p>${pending.length?'<ul class="help-list">'+pending.map(e=>'<li>'+esc(e.title)+'：由接班同事繼續追蹤。</li>').join('')+'</ul>':'<div class="notice">目前沒有待命事件的待辦。</div>'}`;}break;
 case 'bypass':header('未核驗放行？','MANUAL AUTHORIZATION');c.innerHTML=`<p class="spoken">額外箱尚未取得完整授權，你仍要直接放行嗎？</p><p class="lead">系統會保留你的操作與缺少的證據。這不代表一定發生感染，但需要在交班時說明程序缺口。</p><div class="notice">可替代做法：留置並交班、聯絡醫療覆核，或委派給合格代理。</div><div class="dialog-actions">${ui('返回查核','terminal','primary')}${b('仍批准未核驗放行','bypass','danger-button')}</div>`;break;
 case 'settings':header('遊玩設定','ACCESSIBILITY / AUDIO');c.innerHTML=`<div class="setting-row"><label for="setting-sound">合成環境與操作音<small>通風底噪及按鍵音；沒有語音演出</small></label><input id="setting-sound" type="checkbox" data-setting="sound" ${settings.sound?'checked':''}></div><div class="setting-row"><label for="setting-volume">音量<small>可完全靜音</small></label><input id="setting-volume" aria-label="音量" type="range" min="0" max="1" step="0.05" value="${settings.volume}" data-setting="volume"></div><div class="setting-row"><label for="setting-captions">環境聲文字提示</label><input id="setting-captions" type="checkbox" data-setting="captions" ${settings.captions?'checked':''}></div><div class="setting-row"><label for="setting-large">放大文字</label><input id="setting-large" type="checkbox" data-setting="large" ${settings.large?'checked':''}></div><div class="setting-row"><label for="setting-motion">減少動態效果</label><input id="setting-motion" type="checkbox" data-setting="motion" ${settings.motion?'checked':''}></div><div class="notice">目前難度：${DIFFICULTIES[state.difficulty].name}。本機自動存檔。閱讀／對話期間不推進時間。</div><div class="dialog-actions">${ui('操作與試玩範圍','help')}${started?ui('返回標題畫面','title'):''}</div>`;break;
 case 'result':renderResult(c);break;
 case 'reset':header('開始新的值勤','NEW SHIFT');c.innerHTML=`<p class="lead">新遊戲會取代目前裝置上的自動存檔。你可以先匯出本次紀錄，保留不同選擇的結果。</p><div class="dialog-actions"><button class="secondary" data-export="session">匯出本次紀錄</button><button class="primary" data-ui="new-confirm">開始新的一天</button></div>`;break;
 }
 icons(c);plainDom(c);if(hadFocus&&!previous.isConnected){const controls=[...c.querySelectorAll('button:not(:disabled),input,textarea,select,summary')];const matching=controls.find(el=>Object.entries(focusData||{}).some(([key,value])=>['action','ui','event','draft'].includes(key)&&el.dataset[key]===value));const target=matching||controls[Math.min(Math.max(focusIndex,0),controls.length-1)];if(target)target.focus();else{$('#dialog-title').tabIndex=-1;$('#dialog-title').focus();}}
}
function renderRoster(c){header('誰在做什麼','PEOPLE / DUTIES');c.innerHTML=`<p class="lead">這裡只看分工。今天要做的事，請看「上一班的提醒」。</p><table class="roster-table"><thead><tr><th>工作</th><th>今天由誰負責</th><th>可以幫你什麼</th></tr></thead><tbody><tr><td>守門</td><td>你／資深守門人</td><td>接待、顧門、代班</td></tr><tr><td>修理</td><td>工程師</td><td>修機器、檢查排水</td></tr><tr><td>醫療</td><td>醫護</td><td>確認醫療用品</td></tr><tr><td>物資</td><td>後勤</td><td>點貨、保管箱子</td></tr></tbody></table><div class="dialog-actions">${ui('看今天的上班提醒','briefing','primary')}</div><details class="device-details"><summary>下個月怎麼分工（先記草稿）</summary><p class="lead">這不影響今天的工作，月底再討論。</p>${[['gate','守門',['資深守門人','玩家','玩家＋代理輪班']],['engineering','修理',['工程師','工程師＋培訓代理']],['medical','醫療',['醫療負責人','醫療負責人＋培訓代理']],['logistics','物資',['後勤人員','後勤人員＋培訓代理']]].map(([key,label,options])=>`<div class="setting-row"><label for="draft-${key}">${label}</label><select id="draft-${key}" class="field" data-draft="${key}">${options.map(v=>`<option value="${esc(v)}" ${state.rosterDraft[key]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div>`).join('')}</details>`;}
function renderTerminal(c){terminal(state,{header,c,b,ui,esc,actionItem});}
function timeline(e){return `<div class="timeline">${e.entries.map(row=>`<article class="log-entry"><time>9/${15+(row.day??1)}<br>${timeText(row.time)}</time><div><header>${esc(row.type)} · ${esc(row.actor)}</header><p>${esc(row.text)}</p></div></article>`).join('')}</div>`;}
function renderJournal(c){header('事件簿','EVENT REGISTER / AUDIT TRAIL');
 if(selectedEvent){const e=state.events.find(e=>e.id===selectedEvent);if(!e){selectedEvent=null;return renderJournal(c);}c.innerHTML=`<button class="quiet back" data-event="back">← 返回事件列表</button><div class="terminal-meta"><span>${esc(e.id)}</span><span>${esc(e.category)}</span><span class="status-tag amber">${esc(e.status)}</span></div><h3 style="font-size:22px;font-weight:500;margin:8px 0">${esc(e.title)}</h3><div class="notice">承辦：<strong>${esc(e.owner)}</strong> · 通報：9/${15+(e.openedDay??1)} ${timeText(e.opened)} · ${e.closed?'結案：9/'+(15+(e.closedDay??e.openedDay??1))+' '+timeText(e.closed):'尚未結案'}<br>經過 ${Math.max(0,((e.closedDay??(e.closed?e.openedDay:state.day)??1)-(e.openedDay??1))*1440+(e.closed??state.time)-e.opened)} 分鐘。此為事件歷時，非個人工時。既有紀錄不可無痕修改。</div><h3 class="section-title">證據與來源</h3>${e.attachments.length?e.attachments.map(a=>`<details class="evidence"><summary>${esc(a.id)} · ${esc(a.title)}</summary><p>來源：${esc(a.source)} · ${timeText(a.time)}</p><p>${esc(a.content)}</p></details>`).join(''):'<p class="lead">尚無獨立附件，請查看下方工作紀錄。</p>'}<h3 class="section-title">處理時間線</h3>${timeline(e)}${!state.ended?`<form class="note-form" id="note-form"><label for="event-note" hidden>追加事件補註</label><textarea id="event-note" class="field" placeholder="補充觀察或更正說明；原紀錄會保留。" maxlength="500" required aria-label="追加事件補註"></textarea><button class="secondary" type="submit">追加補註</button></form>`:'<div class="notice">本班已結束，紀錄目前為唯讀。</div>'}<button class="secondary" data-export="session">匯出本次紀錄 JSON</button>`;return;}
 c.innerHTML=`<p class="lead">系統事實、人物陳述與處置分開記錄。每一筆都有時間與操作者；補註只追加，不刪除歷史。</p><div class="journal-tools"><input id="event-search" class="field" type="search" placeholder="搜尋事件、人員、時間或紀錄內容" aria-label="搜尋事件"><select id="event-filter" class="field" aria-label="事件狀態篩選"><option value="all">全部狀態</option><option value="open">尚待處理</option><option value="closed">已結案</option></select></div><div id="event-results" class="event-list"></div><div class="dialog-actions"><button class="secondary" data-export="session">匯出本次紀錄</button></div>`;filterJournal();}
function filterJournal(){const q=($('#event-search')?.value||'').toLowerCase(),f=$('#event-filter')?.value||'all';const events=state.events.filter(e=>(JSON.stringify(e)+' '+e.entries.map(r=>timeText(r.time)+' 9/'+(15+(r.day??1))).join(' ')).toLowerCase().includes(q)&&(f==='all'||f==='closed'&&e.status==='已結案'||f==='open'&&e.status!=='已結案'));$('#event-results').innerHTML=events.length?events.map(e=>`<button class="event-row" data-event="${esc(e.id)}"><div><small>${esc(e.id)} · 9/${15+(e.openedDay??1)} ${timeText(e.opened)}</small><span class="status-tag ${e.status==='已結案'?'':'amber'}">${esc(e.status)}</span></div><h3>${esc(e.title)}</h3><small>承辦：${esc(e.owner)} · ${e.entries.length} 筆紀錄 · ${e.attachments.length} 份附件</small></button>`).join(''):'<p class="empty">沒有符合的事件。接班後會建立第一筆設備紀錄。</p>';}
function renderHandover(c){handover(state,{header,c,b,ui,esc});}
function renderResult(c){results(state,{header,c,b,ui,esc});}
function startGame(restore=false){const previous=restore?saved():null;state=previous||createState($('input[name=difficulty]:checked')?.value||'normal');started=true;$('#landing').hidden=true;$('#game').hidden=false;closePanel();render();save();audio.resume();if(state.ended)openPanel('result');}
document.addEventListener('click',async e=>{
 const target=e.target.closest('button');if(!target||target.disabled)return;
 if(target.dataset.move){run('move',{location:target.dataset.move});if($('#tool-dialog').open)closePanel();return;}
 if(target.dataset.action){const action=target.dataset.action;if(action==='sign'||action==='gear'||action==='eat'||action==='visitor'||action==='bypass'||action==='nextDay'||action==='respondIncident'){if(run(action,{choice:target.dataset.choice,id:target.dataset.job})&&$('#tool-dialog').open){closePanel();if(action==='bypass')openPanel('terminal');}}else run(action,{choice:target.dataset.choice,id:target.dataset.job});return;}
 if(target.dataset.openEvent){openPanel('journal');selectedEvent=target.dataset.openEvent;renderPanel();return;}
 if(target.dataset.event){if(target.dataset.event==='back')selectedEvent=null;else selectedEvent=target.dataset.event;renderPanel();$('#dialog-content').scrollTop=0;return;}
 if(target.dataset.export){download(`barn-door-${state.ended?'completed':'in-progress'}-${Date.now()}.json`,JSON.stringify({prototype:'0.4',exportedAt:new Date().toISOString(),...state},null,2));toast('試玩紀錄已匯出。');return;}
 const panel=target.dataset.ui;if(!panel)return;audio.click();
 if(panel==='close'){closePanel();return;}if(panel==='start'){if(saved()){openPanel('reset');return;}startGame();return;}if(panel==='continue'){startGame(true);return;}if(panel==='new-confirm'){startGame();return;}
 if(panel==='title'){closePanel();$('#game').hidden=true;$('#landing').hidden=false;$('#continue-button').hidden=!saved();return;}
 if(panel==='sound'){settings.sound=!settings.sound;await audio.resume();setSettings();return;}
 openPanel(panel);
});
document.addEventListener('change',async e=>{if(e.target.dataset.setting){const key=e.target.dataset.setting;settings[key]=e.target.type==='checkbox'?e.target.checked:Number(e.target.value);if(key==='sound')await audio.resume();setSettings();}if(e.target.dataset.draft){run('draft',{role:e.target.dataset.draft,person:e.target.value});}});
document.addEventListener('input',e=>{if(e.target.id==='event-search')filterJournal();if(e.target.id==='event-filter')filterJournal();if(e.target.dataset.setting==='volume'){settings.volume=Number(e.target.value);setSettings();}});
document.addEventListener('change',e=>{if(e.target.id==='event-filter')filterJournal();});
document.addEventListener('submit',e=>{if(e.target.id==='note-form'){e.preventDefault();const text=$('#event-note').value;if(run('note',{id:selectedEvent,text})){$('#event-note')?.focus();}}});
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(!started||$('#landing').hidden===false)return;if(e.key.toLowerCase()==='j'){e.preventDefault();openPanel('journal');}else if(e.key.toLowerCase()==='r'){e.preventDefault();openPanel('roster');}else if(e.key==='Escape'&&!$('#tool-dialog').open){e.preventDefault();openPanel('settings');}});
$('#tool-dialog').addEventListener('cancel',e=>{e.preventDefault();closePanel();});
$('#tool-dialog').addEventListener('click',e=>{if(e.target===$('#tool-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel();}});
$('#continue-button').hidden=!saved();icons();plainDom($('#landing'));setSettings();

function updateClockMode(){const el=$('#clock-mode');if(!el)return;const label=!started||state.ended?'':state.activeIncident?'新狀況 · 時鐘暫停':mainWorkDone(state)&&state.time<SHIFT_END?(document.hidden?'切換分頁 · 暫停':state.standbyPaused?'已暫停':activePanel?'閱讀中 · 暫停':'待命 · 1 秒 = 1 分鐘'):state.time>=SHIFT_END&&state.signed?'已到交班時間':!state.signed?'準備接班':'工作中';if(el.textContent!==label)el.textContent=label;}
const dutyClock=createClock(performance.now());
setInterval(()=>{const eligible=started&&$('#landing').hidden&&!document.hidden&&!activePanel&&mainWorkDone(state)&&!state.ended&&!state.activeIncident&&!state.standbyPaused&&state.time<SHIFT_END;const ticks=dutyClock.step(performance.now(),eligible);for(let i=0;i<ticks;i++){const before=state,result=act(state,'tick');if(result.error)break;state=result.state;save();if(state.activeIncident){render();openPanel('incident');audio.click();break;}if((before.dutyJob&&!state.dutyJob)||JSON.stringify((before.inheritedJobs||[]).map(j=>j.status))!==JSON.stringify((state.inheritedJobs||[]).map(j=>j.status))){render();toast(state.last);}else if(state.time===SHIFT_END){render();toast(state.last);break;}else{$('#clock').textContent=timeText(state.time);$('#objective').textContent=objective(state);$('#scene-message').textContent=plain(state.last);$('#weather').textContent=state.time>=780?'短暫雷雨 · 25°C':'多雲 · 26°C';}}updateClockMode();},250);
document.addEventListener('visibilitychange',()=>{dutyClock.step(performance.now(),false);updateClockMode();});

function updateWorkboardCount(){const el=$('#backlog-count');if(el)el.textContent=String((state.inheritedJobs||[]).filter(j=>j.status==='待安排').length);}
